public object FfiConverterTypeTextGenerator: FfiConverter<TextGenerator, Long> {
    internal val handleMap = UniffiHandleMap<TextGenerator>()

    override fun lower(value: TextGenerator): Long {
        if (value is TextGeneratorImpl) {
             // Rust-implemented object.  Clone the handle and return it
            return value.uniffiCloneHandle()
         } else {
            // Kotlin object, generate a new vtable handle and return that.
            return handleMap.insert(value)
         }
    }

    override fun lift(value: Long): TextGenerator {
        if ((value and 1.toLong()) == 0.toLong()) {
            // Rust-generated handle, construct a new class that uses the handle to implement the
            // interface
            return TextGeneratorImpl(UniffiWithHandle, value)
        } else {
            // Kotlin-generated handle, get the object from the handle map
            return handleMap.remove(value)
        }
    }

    override fun read(buf: ByteBuffer): TextGenerator {
        return lift(buf.getLong())
    }

    override fun allocationSize(value: TextGenerator) = 8UL

    override fun write(value: TextGenerator, buf: ByteBuffer) {
        buf.putLong(lower(value))
    }
}



