public object FfiConverterTypeAuthorizationMethod : FfiConverterRustBuffer<AuthorizationMethod>{
    override fun read(buf: ByteBuffer): AuthorizationMethod {
        return when(buf.getInt()) {
            1 -> AuthorizationMethod.Oauth
            2 -> AuthorizationMethod.Password(
                FfiConverterSequenceTypeCredentialField.read(buf),
                )
            3 -> AuthorizationMethod.System
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: AuthorizationMethod): ULong = when(value) {
        is AuthorizationMethod.Oauth -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
        is AuthorizationMethod.Password -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterSequenceTypeCredentialField.allocationSize(value.`fields`)
            )
        }
        is AuthorizationMethod.System -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
    }

    override fun write(value: AuthorizationMethod, buf: ByteBuffer) {
        when(value) {
            is AuthorizationMethod.Oauth -> {
                buf.putInt(1)
                Unit
            }
            is AuthorizationMethod.Password -> {
                buf.putInt(2)
                FfiConverterSequenceTypeCredentialField.write(value.`fields`, buf)
                Unit
            }
            is AuthorizationMethod.System -> {
                buf.putInt(3)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
