/**
 * The one error every throwing call of the bindings can throw (mirrors `Failure`, plus a rejected configuration).
 */
sealed class FfiException: kotlin.Exception() {
    
    /**
     * A connector's own error.
     */
    class Source(
        
        val v1: SourceError
        ) : FfiException() {
        override val message
            get() = "v1=${ v1 }"
    }
    
    /**
     * The host cancelled, or the engine did.
     */
    class Cancelled(
        ) : FfiException() {
        override val message
            get() = ""
    }
    
    /**
     * A write refused or failed.
     */
    class Write(
        
        val v1: WriteError
        ) : FfiException() {
        override val message
            get() = "v1=${ v1 }"
    }
    
    /**
     * A failure the host reported, as text.
     */
    class Host(
        
        /**
         * The host's description.
         */
        val `detail`: kotlin.String
        ) : FfiException() {
        override val message
            get() = "detail=${ `detail` }"
    }
    
    /**
     * The configuration or an argument the host passed is not acceptable.
     */
    class InvalidConfig(
        
        /**
         * What is wrong.
         */
        val `reason`: kotlin.String
        ) : FfiException() {
        override val message
            get() = "reason=${ `reason` }"
    }
    

    


    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<FfiException> {
        override fun lift(error_buf: RustBuffer.ByValue): FfiException = FfiConverterTypeFfiError.lift(error_buf)
    }

    
}

