/**
 * What a host callback may throw: the five kinds of the C interface's reply errors.
 */
sealed class HostException: kotlin.Exception() {
    
    /**
     * The host could not reach the network.
     */
    class Network(
        
        /**
         * The host's description; may be empty.
         */
        val `detail`: kotlin.String
        ) : HostException() {
        override val message
            get() = "detail=${ `detail` }"
    }
    
    /**
     * The user or the host cancelled.
     */
    class Cancelled(
        ) : HostException() {
        override val message
            get() = ""
    }
    
    /**
     * The thing asked for does not exist.
     */
    class NotFound(
        ) : HostException() {
        override val message
            get() = ""
    }
    
    /**
     * The host refused, for example for lack of permission.
     */
    class Denied(
        ) : HostException() {
        override val message
            get() = ""
    }
    
    /**
     * Any other failure.
     */
    class Failed(
        
        /**
         * The host's description; may be empty.
         */
        val `detail`: kotlin.String
        ) : HostException() {
        override val message
            get() = "detail=${ `detail` }"
    }
    

    


    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<HostException> {
        override fun lift(error_buf: RustBuffer.ByValue): HostException = FfiConverterTypeHostError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeHostError : FfiConverterRustBuffer<HostException> {
    override fun read(buf: ByteBuffer): HostException {
        

        return when(buf.getInt()) {
            1 -> HostException.Network(
                FfiConverterString.read(buf),
                )
            2 -> HostException.Cancelled()
            3 -> HostException.NotFound()
            4 -> HostException.Denied()
            5 -> HostException.Failed(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: HostException): ULong {
        return when(value) {
            is HostException.Network -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`detail`)
            )
            is HostException.Cancelled -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is HostException.NotFound -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is HostException.Denied -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is HostException.Failed -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`detail`)
            )
        }
    }

    override fun write(value: HostException, buf: ByteBuffer) {
        when(value) {
            is HostException.Network -> {
                buf.putInt(1)
                FfiConverterString.write(value.`detail`, buf)
                Unit
            }
            is HostException.Cancelled -> {
                buf.putInt(2)
                Unit
            }
            is HostException.NotFound -> {
                buf.putInt(3)
                Unit
            }
            is HostException.Denied -> {
                buf.putInt(4)
                Unit
            }
            is HostException.Failed -> {
                buf.putInt(5)
                FfiConverterString.write(value.`detail`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}



